import {api,ApiError,isConfigured,mediaUrl,setToken,getToken} from './api.js';
import {CONTENT} from './public-content.js';
const $=(sel,root=document)=>root.querySelector(sel);
const $$=(sel,root=document)=>Array.from(root.querySelectorAll(sel));
const page=document.body.dataset.page||'index';
const qs=new URLSearchParams(location.search);
const escapeHtml = x=>String(x??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const e=escapeHtml;
let lang=localStorage.getItem('as.lang')==='kz'?'kz':'ru';
const words={ru:{home:'Главная',library:'Библиотека',learn:'Учиться',play:'Практика',personal:'Личный кабинет',teacher:'Кабинет учителя',admin:'Управление материалами',login:'Войти',logout:'Выйти',start:'Начать обучение',more:'Подробнее',search:'Поиск',all:'Все категории',save:'Сохранить',back:'Назад',next:'Дальше',submit:'Завершить',empty:'Пока ничего нет',notsetup:'Сервер пока не подключён',status:'Статус сервера'},kz:{home:'Басты бет',library:'Кітапхана',learn:'Оқу',play:'Жаттығулар',personal:'Жеке кабинет',teacher:'Мұғалім кабинеті',admin:'Материалдарды басқару',login:'Кіру',logout:'Шығу',start:'Оқуды бастау',more:'Толығырақ',search:'Іздеу',all:'Барлық санат',save:'Сақтау',back:'Артқа',next:'Келесі',submit:'Аяқтау',empty:'Әзірге ештеңе жоқ',notsetup:'Сервер әлі қосылмаған',status:'Сервер күйі'}};
const t=(name)=>words[lang]?.[name]||words.ru[name]||name;
const navGroups=[
 {name:'Главное',nameKz:'Негізгі',links:[['index','⌂','home'],['library','▤','library'],['ai','✦','AI-помощник / AI көмекші']]},
 {name:'Исследуй и проверяй',nameKz:'Ойлан және тексер',links:[['diagnostic','◉','Диагностика'],['tests','☑','Тест без подсказок'],['catch','◎','Поймай списывающего'],['error404','⚡','Ошибка 404'],['battle','⚔','Битва с ИИ']]},
 {name:'Создавай',nameKz:'Өзің құрастыр',links:[['gps','◈','GPS мышления'],['essay','✎','Конструктор сочинений'],['dictionary','▧','Русский без паники'],['detective','⌕','Литературный детектив']]},
 {name:'Мой кабинет',nameKz:'Жеке кабинет',links:[['progress','◷','Мой прогресс'],['teacher','▦','teacher'],['admin','⚙','admin']]}
];
const titles={index:'Самостоятельно — значит уверенно',library:'Библиотека материалов',material:'Учебный материал',diagnostic:'Диагностика',tests:'Тест без подсказок',catch:'Поймай списывающего',error404:'Ошибка 404',battle:'Битва с ИИ',gps:'GPS самостоятельного мышления',essay:'Конструктор сочинений',dictionary:'Русский без паники',detective:'Литературный детектив',ai:'Не списывай, подумай!',progress:'Мой прогресс',teacher:'Кабинет учителя',admin:'Управление материалами',login:'Вход / регистрация'};
const colorCategories={lesson:'Урок',literature:'Литература',task:'Задание',case:'Кейс',resource:'Ресурс',essay:'Сочинение'};
const coverFor=cat=>({literature:'cover-reading.svg',lesson:'cover-thinking.svg',resource:'cover-reading.svg',task:'cover-thinking.svg',case:'cover-reading.svg',essay:'cover-writing.svg'}[cat]||'cover-reading.svg');
const cover=m=>m?.cover_key&&mediaUrl(m.cover_key)||`assets/${coverFor(m?.category)}`;
const state={user:null,error:null,data:null,loading:false,category:'all',search:'',pg:1,exercises:[],exKind:'',phase:'pre',index:0,answers:{},grade:null,gameIdx:0,gameType:'Лови ошибку',gameLevel:1,gameDone:false,materials:[],currentMaterial:null,history:[],draft:null,draftVersion:0,chat:[],selectedMaterial:'',progress:null,teacher:null,editId:'',editing:null,manage:false};
const root=$('#app');
const p=(text)=>`<p>${e(text)}</p>`;
function htmlShell(content){
 const user=state.user;
 const nav=navGroups.map(g=>`<div class="nav-group">${e(lang==='kz'?g.nameKz:g.name)}</div><nav class="nav" aria-label="${e(g.name)}">${g.links.filter(([id])=>(id!=='teacher'&&id!=='admin')||user&&['teacher','admin'].includes(user.role)).map(([id,icon,label])=>`<a href="${id}.html" class="${page===id||page==='material'&&id==='library'?'active':''}" ${page===id||page==='material'&&id==='library'?'aria-current="page"':''}><span class="symbol" aria-hidden="true">${icon}</span><span>${e(words[lang]?.[label]||label)}</span>${page===id?'<span class="arrow" aria-hidden="true">●</span>':''}</a>`).join('')}</nav>`).join('');
 return `<div class="mobile-cover" id="mobile-cover"></div><div class="layout"><aside class="side" id="sidebar"><a class="brand" href="index.html" aria-label="Антисписывание · Главная"><span class="brand-mark" aria-hidden="true">↗</span><span>АНТИСПИСЫВАНИЕ<small>ДУМАЙ · ДОКАЗЫВАЙ · РАСТИ</small></span></a>${nav}<div class="side-bottom">✦ 9 класс · Русский язык и литература<br><b>Казахский язык обучения</b></div></aside><div class="main"><header class="topbar"><div style="display:flex;align-items:center;gap:12px"><button class="menu-toggle" id="nav-toggle" aria-controls="sidebar" aria-expanded="false" aria-label="Открыть меню">☰</button><div class="crumb">ПЛАТФОРМА / ${e(titles[page]||'АНТИСПИСЫВАНИЕ')}</div></div><div class="top-actions"><div class="lang-switch" role="group" aria-label="Язык интерфейса"><button type="button" data-lang="ru" class="${lang==='ru'?'active':''}" aria-pressed="${lang==='ru'}">RU</button><button type="button" data-lang="kz" class="${lang==='kz'?'active':''}" aria-pressed="${lang==='kz'}">KZ</button></div><a class="user-chip" href="${user?'progress.html':'login.html'}">${user?'● '+e(user.handle):'↗ '+t('login')}</a></div></header><main class="page" id="page-content">${content}</main></div></div>`;
}
function intro(label,title,subtitle,actions=''){return `<div class="intro"><div class="eyebrow">${e(label)}</div><h1>${e(title)}</h1>${p(subtitle)}${actions}</div>`}
const spinner=(s='Загружаем данные…')=>`<div class="empty" role="status"><span class="emoji">◌</span><h3>${e(s)}</h3><p>Проверяем связь с сервером.</p></div>`;
const noServer=()=>`<div class="callout warn" role="status"><b>${t('notsetup')}.</b> Жоба файлы дайын, бірақ Cloudflare Worker әлі жарияланбаған немесе <code>js/config.js</code> ішіне нақты URL енгізілмеген. Бұл бөлімде деректер ойдан көрсетілмейді.</div>`;
function empty(title='Здесь пока нет опубликованных материалов',desc='Учитель добавит материалы в кабинете управления.'){return `<div class="empty"><span class="emoji">◌</span><h3>${e(title)}</h3><p>${e(desc)}</p></div>`}
function statusBanner(){return !isConfigured()?noServer():state.error?`<div role="alert" class="callout error">${e(state.error)}</div>`:''}
function toast(message,err=false){const old=$('.notice');if(old)old.remove();const div=document.createElement('div');div.className='notice'+(err?' err':'');div.setAttribute('role','status');div.textContent=message;document.body.appendChild(div);setTimeout(()=>div.remove(),4700)}
function guard(role='student'){if(!state.user)return `<div class="panel"><h2>Для продолжения нужен личный профиль</h2><p class="muted">Создайте условный код вместо настоящего имени. Все результаты хранятся в общей базе только после подтверждённого входа.</p><a href="login.html" class="btn">Войти или зарегистрироваться</a></div>`;if(role==='teacher'&&!['teacher','admin'].includes(state.user.role))return `<div class="callout error">Нет доступа. Этот раздел доступен только учителю.</div>`;return null}
function cardlink(href,icon,title,desc){return `<a href="${href}" class="tile"><div class="tile-icon" aria-hidden="true">${icon}</div><h3>${e(title)}</h3><p>${e(desc)}</p><div class="tile-foot">Открыть ↗</div></a>`}
function stat(label,val){return `<div class="stat"><strong>${e(val)}</strong><span>${e(label)}</span></div>`}
function renderHome(){return `<div class="hero"><div class="hero-content"><span class="eyebrow">9 КЛАСС · РУССКИЙ ЯЗЫК И ЛИТЕРАТУРА</span><h1>Списать легко.<br>Понять — круче.</h1><p>Учимся не копировать ответы, а задавать вопросы, находить доказательства и защищать собственную мысль.</p><div class="hero-actions"><a class="btn" href="${state.user?'diagnostic.html':'login.html'}">${t('start')} ↗</a><a class="btn ghost" href="library.html">${t('library')}</a></div></div><div class="hero-art"><img src="assets/hero.svg" width="720" height="535" alt="Иллюстрация: лист с вопросом, текстом и отметкой проверки"></div></div>
 <div class="section-head"><div><h2>Учись в своём ритме</h2><p>Всё важное — в одном-двух нажатиях.</p></div><a href="library.html" class="link">Все материалы →</a></div>
 <div class="tile-grid">${cardlink('diagnostic.html','◉','Проверь себя','Входная диагностика и сравнение «до/после».')}${cardlink('ai.html','✦','Спроси AI-помощника','Наводящие вопросы вместо готового сочинения.')}${cardlink('error404.html','⚡','Тренировка без скуки','Найди ошибку, расставь знаки, собери фразу.')}${cardlink('gps.html','◈','Маршрут мышления','Пойми → Подумай → Докажи → Проверь → Защити.')}${cardlink('essay.html','✎','Моя собственная работа','Черновик, аргументы и улучшенная версия.')}${cardlink('progress.html','◷','Мои результаты','История прохождений и динамика навыков.')}</div>
 <div class="section-head"><div><h2>Не угадывай. Доказывай.</h2><p>Авторские учебные задания, подготовленные для этой платформы.</p></div></div><div class="split equal"><div class="panel"><span class="badge">Шаг 01</span><h3 style="margin-top:13px">Задай себе вопрос</h3><p class="muted">Что именно утверждается? Каким примером это подтверждается? Есть ли другое объяснение?</p></div><div class="panel"><span class="badge purple">Шаг 02</span><h3 style="margin-top:13px">Проверь источник</h3><p class="muted">Не доверяй даже красиво написанному ответу — сопоставь его с оригиналом.</p></div></div>${!isConfigured()?`<div style="margin-top:18px">${noServer()}</div>`:''}`}
function renderLogin(){if(state.user)return intro('УЧЁТНАЯ ЗАПИСЬ','Вы уже вошли',`Код: ${state.user.handle}. Роль: ${state.user.role}.`,`<div class="form-actions"><a class="btn" href="progress.html">Мой прогресс ↗</a><button class="btn danger" id="logout">Выйти</button></div>`);
return `${intro('БЕЗ ФИО И ЛИШНИХ ДАННЫХ','Начни под своим кодом','Используй вымышленный код (например, reader_09), а не полное имя. Учителя получают отдельный аккаунт от администратора.')}${statusBanner()}<div class="split equal" style="margin-top:18px"><form id="login-form" class="panel"><span class="badge">Есть аккаунт</span><h2 style="margin-top:12px">Вход</h2><div class="fields"><div class="field wide"><label for="login-handle">Код ученика / логин</label><input id="login-handle" name="handle" minlength="3" maxlength="24" required autocomplete="username" pattern="[A-Za-z0-9_-]{3,24}"></div><div class="field wide"><label for="login-password">Пароль</label><input type="password" id="login-password" name="password" minlength="10" required autocomplete="current-password"></div></div><div class="form-actions"><button class="btn" type="submit">Войти ↗</button></div></form>
<form id="register-form" class="panel"><span class="badge orange">Первый раз</span><h2 style="margin-top:12px">Создать профиль</h2><div class="fields"><div class="field wide"><label for="reg-handle">Придумай код</label><input id="reg-handle" name="handle" minlength="3" maxlength="24" pattern="[A-Za-z0-9_-]{3,24}" placeholder="reader_09" autocomplete="username" required><span class="hint">Латинские буквы, цифры, _ и −. Не вводи ФИО.</span></div><div class="field wide"><label for="reg-password">Придумай пароль</label><input id="reg-password" type="password" name="password" minlength="10" maxlength="128" autocomplete="new-password" required></div></div><div class="form-actions"><button class="btn pale" type="submit">Создать и войти ↗</button></div></form></div><div class="callout info" style="margin-top:18px">Пароль хранится в базе в виде солёного PBKDF2-хэша. Сессия действует до 7 дней на одном браузере; закрытие вкладки может завершить локальную сессию.</div>`}
function matCard(m){return `<a class="mat-card" href="material.html?id=${encodeURIComponent(m.id)}"><img loading="lazy" src="${e(cover(m))}" alt="Обложка материала: ${e(m.title)}"><div class="mat-card-body"><div><span class="badge ${m.category==='essay'?'orange':''}">${e(colorCategories[m.category]||m.category)}</span></div><h3>${e(m.title)}</h3><p>${e(m.description||m.content.slice(0,120))}</p><footer><span class="micro muted">9 класс · авторский материал</span><span class="link">Читать ↗</span></footer></div></a>`}
function renderLibrary(){return `${intro('КОЛЛЕКЦИЯ ЗНАНИЙ','Библиотека','Материалы добавляются учителем через управление, а после публикации автоматически появляются здесь.')}${statusBanner()}<form class="toolbar" id="search-library"><div class="field"><label for="lib-search">${t('search')} по названию и тексту</label><input id="lib-search" name="search" value="${e(state.search)}" placeholder="Например: аргументация"></div><div class="field small-field"><label for="lib-category">Категория</label><select id="lib-category" name="category"><option value="all">${t('all')}</option>${Object.entries(colorCategories).map(([id,name])=>`<option value="${id}" ${state.category===id?'selected':''}>${e(name)}</option>`).join('')}</select></div><button type="submit" class="btn" style="min-height:47px">Найти</button></form>${state.loading?spinner():state.data?.items?.length?`<div class="card-list">${state.data.items.map(matCard).join('')}</div>${pager()}`:empty(state.error?'Материалы не загружены':'Материалов не найдено',state.error||'Попробуй изменить запрос или фильтр.')}`}
function pager(){if(!state.data)return '';const {page:p,total,page_size:s}=state.data;return `<div class="pager"><button class="btn soft tiny" data-page-index="${p-1}" ${p<=1?'disabled':''}>←</button><span class="small muted">Страница ${p} из ${Math.max(1,Math.ceil(total/s))} · ${total} записей</span><button class="btn soft tiny" data-page-index="${p+1}" ${p*s>=total?'disabled':''}>→</button></div>`}
function renderMaterial(){let m=state.currentMaterial;return `${intro('БИБЛИОТЕКА',m?.title||'Учебный материал',m?.description||'Подробности выбранного материала','<a href="library.html" class="link">← Вернуться в библиотеку</a>')}${statusBanner()}${state.loading?spinner():!m?empty('Материал не открыт',state.error||'Он может быть не опубликован или удалён.'): `<div class="split"><article class="panel"><img class="material-cover" src="${e(cover(m))}" alt="Обложка: ${e(m.title)}"><div style="margin:18px 0"><span class="badge">${e(colorCategories[m.category]||m.category)}</span> <span class="badge gray">${e(m.author_label||'Авторский учебный материал')}</span></div><div class="text-reading">${e(m.content)}</div></article><aside class="column-stack"><div class="panel"><h3>Как работать с материалом?</h3><p class="muted small">Прочитай → выдели главную мысль → придумай аргумент → проверь себя.</p>${m.category==='task'?`<a class="btn full" href="tests.html?material_id=${encodeURIComponent(m.id)}">Выполнить задание ↗</a><a class="btn soft full" style="margin-top:9px" href="ai.html?material_id=${encodeURIComponent(m.id)}">Обсудить с AI ↗</a>`:`<a class="btn full" href="ai.html?material_id=${encodeURIComponent(m.id)}">Обсудить с AI ↗</a><a class="btn soft full" style="margin-top:9px" href="essay.html?material_id=${encodeURIComponent(m.id)}">Написать текст</a>`}</div><div class="panel"><h3>Дополнительно</h3>${m.attachment_key?`<a class="link" target="_blank" rel="noopener noreferrer" href="${e(mediaUrl(m.attachment_key))}">Скачать документ ↗</a><br>`:''}${m.reference_url?`<a class="link" target="_blank" rel="noopener noreferrer" href="${e(m.reference_url)}">Источник ↗</a><br>`:''}${m.video_url?`<a class="link" target="_blank" rel="noopener noreferrer" href="${e(m.video_url)}">Открыть видео по ссылке ↗</a>`:''}${!m.reference_url&&!m.video_url&&!m.attachment_key?'<p class="muted small">Внешние ссылки не добавлены.</p>':''}</div></aside></div>`}`}
function exerciseHead(title,subtitle){return intro('ТРЕНИРУЙ МЫШЛЕНИЕ',title,subtitle)}
function renderQuiz(kind){const diagnostic=kind==='diagnostic',singleMaterial=kind==='task',title=diagnostic?'Диагностика':singleMaterial?'Задание из библиотеки':'Тест без подсказок';const sub=diagnostic?'Два разных набора по 20 заданий: смысловое чтение, грамматика, речевые нормы и аргументация.':singleMaterial?'Ответь на вопрос по опубликованному учителем материалу.':'Правильные ответы и объяснения появятся только после завершения.';let toolbar='';
 if(diagnostic)toolbar=`<div class="topic-pills"><button class="pill ${state.phase==='pre'?'active':''}" data-phase="pre">Входная диагностика</button><button class="pill ${state.phase==='post'?'active':''}" data-phase="post">Итоговая диагностика</button></div>`;
 if(!diagnostic&&!singleMaterial){const cats=['all','Орфография','Пунктуация','Сложное предложение','Лексика','Стили речи','Литература'];toolbar=`<div class="topic-pills">${cats.map(cat=>`<button class="pill ${state.category===cat?'active':''}" data-quiz-category="${e(cat)}">${e(cat==='all'?'Все темы':cat)}</button>`).join('')}</div>`}
 let content='';if(state.grade)content=resultBlock();else if(state.loading)content=spinner('Готовим задания…');else if(!state.exercises.length)content=empty('Задания не получены',state.error||'Связь с сервером необходима для честной проверки.');else {let q=state.exercises[state.index];content=`<div class="panel"><div class="question-meta"><span>${e(q.c||title)}</span><span>Вопрос ${state.index+1} / ${state.exercises.length}</span></div><div class="question-progress" role="progressbar" aria-valuenow="${state.index+1}" aria-valuemin="1" aria-valuemax="${state.exercises.length}"><i style="width:${(state.index+1)/state.exercises.length*100}%"></i></div><h2 class="question">${e(q.q)}</h2><div class="choices" role="radiogroup" aria-label="Ответ на вопрос">${(q.a||[]).map((choice,i)=>`<label class="choice"><input type="radio" name="answer" value="${i}" ${Number(state.answers[q.id])===i?'checked':''}><span class="letter">${String.fromCharCode(65+i)}</span><span>${e(choice)}</span></label>`).join('')}</div><div class="form-actions"><button class="btn soft" data-quiz-action="prev" ${state.index===0?'disabled':''}>← ${t('back')}</button><button class="btn" data-quiz-action="next">${state.index===state.exercises.length-1?t('submit'):t('next')+' →'}</button></div><p class="micro muted">Ответы не показываются до завершения теста. Прогресс сохранится на сервере после отправки.</p></div>`}
 return `${exerciseHead(title,sub)}${statusBanner()}${guard()||`<div style="margin:17px 0 20px">${toolbar}</div>${content}`}`;
}
function resultBlock(){const r=state.grade;return `<div class="panel"><div class="eyebrow">РЕЗУЛЬТАТ СОХРАНЁН В D1</div><h2>Твой результат: ${r.score} / ${r.total}</h2><p class="muted">${Math.round(r.total?100*r.score/r.total:0)}% правильных ответов. Просмотри объяснения, прежде чем начать новый тест.</p>${r.breakdown?`<div class="two-col">${Object.entries(r.breakdown).map(([label,v])=>`<div class="callout"><b>${e(label)}</b> · ${v.score}/${v.total}</div>`).join('')}</div>`:''}${r.notice?`<p class="callout info">${e(r.notice)}</p>`:''}${page==='diagnostic'&&r.breakdown?`<div class="callout info" style="margin:12px 0"><b>Индивидуальная рекомендация:</b> ${e((()=>{const weak=Object.entries(r.breakdown).sort((a,b)=>a[1].score/a[1].total-b[1].score/b[1].total)[0];return weak?'Начни с навыка «'+weak[0]+'». Перечитай пояснения к ошибкам и попробуй другое задание.':'Повтори тему и обоснуй свой ответ.'})())}</div>`:''}${page==='error404'?`<p class="badge purple">${r.score?'★ Звезда за верный ответ':'☆ Попробуй другой уровень'}</p>`:''}<div style="margin-top:16px">${(r.details||[]).map((d,i)=>`<div class="result-item"><div class="result-q">${i+1}. ${e(d.question||d.claim)}</div><span class="${d.correct?'correct':'incorrect'}">${d.correct?'✓ Верно':'× Неточно'}</span><div class="small muted">${d.explanation?e(d.explanation):''}${d.answer!==undefined?` · Правильный вариант: ${Number(d.answer)+1}`:''}${d.shouldMark!==undefined?` · ${d.shouldMark?'Утверждение подтверждается / отмечено по правилу задания':'Не подтверждается / не надо отмечать'}`:''}</div></div>`).join('')}</div><div class="form-actions"><button class="btn" id="restart-exercise">Попробовать ещё раз</button><a class="btn soft" href="progress.html">Мой прогресс →</a>${qs.get('material_id')?`<a class="btn pale" href="ai.html?material_id=${encodeURIComponent(qs.get('material_id'))}">Обсудить с AI ↗</a>`:''}</div></div>`}
function renderCatch(){const title='Поймай списывающего';const items=state.exercises;const item=items[state.gameIdx%Math.max(1,items.length)];return `${exerciseHead(title,'Проверь готовый ответ по исходному тексту. Баллы — за обнаружение ошибок и письменное объяснение.')}${statusBanner()}${guard()|| (state.loading?spinner():state.grade?resultBlock():item?`<div class="split"><div class="panel"><span class="badge purple">Исходный текст</span><h2 style="margin-top:13px">${e(item.title)}</h2><div class="quote">${e(item.source)}</div><p class="small muted">Авторский учебный пример. Утверждения ниже могут быть ложными.</p></div><form class="panel" id="catch-form"><h3>Отметь подозрительные утверждения</h3><div class="choices">${item.claims.map((cl,i)=>`<label class="choice"><input type="checkbox" name="claim" value="${i}"><span>${e(cl)}</span></label>`).join('')}</div><div class="field" style="margin-top:18px"><label for="catch-reason">Почему ты так решил(а)?</label><textarea id="catch-reason" minlength="20" maxlength="3000" required placeholder="Укажи, что именно не совпадает с исходным текстом"></textarea></div><div class="form-actions"><button class="btn" type="submit">Проверить аргументы →</button><button type="button" class="btn soft" id="next-game">Другой случай</button></div></form></div>`:empty('Нет случаев','Проверь подключение к серверу.'))}`}
function renderError404(){const games=state.exercises,types=['Лови ошибку','Пунктуация','Собери фразу','Точное слово'];let q=games.find(v=>v.type===state.gameType&&v.level===state.gameLevel);return `${exerciseHead('Ошибка 404','Четыре механики · три уровня сложности. Ответы проверяются сервером, без подсказок заранее.')}${statusBanner()}${guard()||`<div class="topic-pills" style="margin-bottom:13px">${types.map(ty=>`<button class="pill ${state.gameType===ty?'active':''}" data-error-type="${e(ty)}">${e(ty)}</button>`).join('')}</div><div class="topic-pills" style="margin-bottom:20px">${[1,2,3].map(n=>`<button class="pill ${state.gameLevel===n?'active':''}" data-error-level="${n}">${n} уровень</button>`).join('')}</div>${state.loading?spinner():state.grade?resultBlock():q?`<div class="panel" style="max-width:800px"><div class="question-meta"><span>${e(q.type)}</span><span>Уровень ${q.level} / 3</span></div><h2 class="question">${e(q.q)}</h2><form id="error-form"><div class="choices">${q.a.map((a,i)=>`<label class="choice"><input required name="answer" value="${i}" type="radio"><span class="letter">${String.fromCharCode(65+i)}</span>${e(a)}</label>`).join('')}</div><div class="form-actions"><button class="btn" type="submit">Проверить →</button></div></form></div>`:empty('Игра не загружена','Сервер недоступен.')}`}`}
function renderBattle(){const x=state.exercises[0];return `${exerciseHead('Битва с ИИ','Предварительно подготовленная ошибочная интерпретация — учебный пример, а НЕ живой ответ AI. Сравни её с исходным текстом.')}${statusBanner()}${guard()|| (state.loading?spinner():state.grade?resultBlock():x?`<div class="split"><div class="column-stack"><div class="panel"><span class="badge">Исходный фрагмент</span><div class="quote" style="margin-top:14px">${e(x.passage)}</div></div><div class="panel"><span class="badge orange">Ошибочная интерпретация (подготовлена заранее)</span><p class="text-reading" style="margin:13px 0">${e(x.ai)}</p></div></div><form class="panel" id="battle-form"><h3>Какие утверждения подтверждаются текстом?</h3><p class="small muted">Отметь те, которые действительно следуют из фрагмента.</p><div class="choices">${x.statements.map((s,i)=>`<label class="choice"><input type="checkbox" name="claim" value="${i}">${e(s)}</label>`).join('')}</div><div class="field" style="margin-top:18px"><label for="battle-position">Моя собственная позиция (от 50 символов)</label><textarea id="battle-position" minlength="50" maxlength="4000" required placeholder="Я считаю…, потому что в тексте сказано…"></textarea></div><div class="callout info" style="margin-top:13px">Рубрика учителя: смысл, доказательства, логика, речевое оформление. Автоматически проверяются только конкретные утверждения.</div><div class="form-actions"><button class="btn" type="submit">Завершить битву →</button></div></form></div>`:empty('Пример недоступен','Подключите сервер.'))}`}
function renderDetective(){const x=state.exercises[state.gameIdx%Math.max(1,state.exercises.length)];return `${exerciseHead('Литературный детектив','Авторские короткие фрагменты: найди мотив героя, проверь деталь и объясни свой вывод.')}${statusBanner()}${guard()||(state.loading?spinner():state.grade?resultBlock():x?`<div class="split"><div class="panel"><span class="badge">История ${state.gameIdx+1} / ${state.exercises.length}</span><h2 style="margin-top:12px">${e(x.title)}</h2><div class="quote">${e(x.passage)}</div></div><form class="panel" id="detective-form"><h3>${e(x.q)}</h3><div class="choices">${(x.options||[]).map((a,i)=>`<label class="choice"><input required type="radio" name="answer" value="${i}">${e(a)}</label>`).join('')}</div><h3 style="margin-top:18px">${e(x.detailQ||'Выбери текстовое доказательство')}</h3><div class="choices">${(x.details||[]).map((a,i)=>`<label class="choice"><input required type="radio" name="detail" value="${i}">${e(a)}</label>`).join('')}</div><div class="field" style="margin-top:17px"><label for="det-reason">Объяснение (от 20 символов)</label><textarea id="det-reason" minlength="20" maxlength="3000" required></textarea></div><div class="form-actions"><button class="btn" type="submit">Проверить →</button><button class="btn soft" type="button" id="next-game">Следующая история</button></div></form></div>`:empty('Фрагмент не получен','Подключение к серверу требуется.'))}`}
function renderGps(){const steps=CONTENT.gpsPrompts;let idx=state.index;const current=steps[idx];return `${intro('5 ЭТАПОВ','GPS самостоятельного мышления','Пойми → Подумай → Докажи → Проверь → Защити. Каждый этап фиксирует твою собственную мысль.')}${statusBanner()}${guard()||`<div class="route-steps">${steps.map((s,i)=>`<div class="route-step ${i<idx?'done':i===idx?'current':''}">${i+1}. ${e(s.name)}</div>`).join('')}</div><div class="split"><form class="panel" id="gps-form"><span class="badge">Шаг ${idx+1} из 5</span><h2 style="margin-top:12px">${e(current.name)}</h2><p class="muted">${e(current.hint)}</p><div class="field"><label for="gps-response">Мой ответ</label><textarea id="gps-response" required minlength="12" maxlength="2200" placeholder="${e(current.example)}">${e(state.answers[idx]||'')}</textarea></div><div class="form-actions"><button class="btn soft" type="button" id="gps-prev" ${idx===0?'disabled':''}>← Назад</button><button class="btn" type="submit">${idx===4?'Сохранить маршрут':'Следующий шаг →'}</button></div></form><div class="panel subtle"><h3>Почему это работает?</h3><p>Вместо того чтобы просто повторить готовый ответ, ты проходишь путь от понимания к доказательству.</p><p class="small muted">Текст сохраняется на сервере после завершения всех пяти шагов. Для черновика есть отдельное сохранение.</p><button id="gps-draft" class="btn soft">Сохранить черновик</button>${state.draft?.payload?'<p class="small muted" style="margin-top:12px">Черновик загружен из D1.</p>':''}</div></div>`}`}
function renderEssay(){let draft=state.draft?.payload||{};let m=state.currentMaterial;let topics=CONTENT.essayTopics;const opt=topics.map(x=>`<option value="${e(x)}" ${draft.topic===x?'selected':''}>${e(x)}</option>`).join('');const fields=[['thesis','Тезис','Какова твоя позиция?'],['arg1','Первый аргумент','Конкретный пример из текста или жизни'],['arg2','Второй аргумент','Ещё одно проверяемое доказательство'],['plan','План','Введение → доказательства → вывод'],['first','Первая версия','Не бойся черновика'],['revised','Исправленная версия','Что улучшилось после проверки?'],['conclusion','Вывод','Вернись к тезису']];return `${intro('ПИШИ САМ','Конструктор сочинений','Выбирай тему, строй доказательства, сохраняй черновик и сравнивай версии. Содержание оценивает учитель, а AI предлагает подсказки.')}${statusBanner()}${guard()||`<div class="split"><form class="panel" id="essay-form"><div class="fields"><div class="field wide"><label for="essay-topic">Тема сочинения</label><select id="essay-topic" name="topic">${m?`<option value="${e(m.title)}" ${draft.topic===m.title?'selected':''}>По материалу: ${e(m.title)}</option>`:''}${opt}</select></div>${fields.map(([id,label,hint])=>`<div class="field wide"><label for="essay-${id}">${label}</label><textarea id="essay-${id}" name="${id}" maxlength="5000" placeholder="${e(hint)}">${e(draft[id]||'')}</textarea></div>`).join('')}</div><div class="form-actions"><button class="btn soft" type="button" id="essay-draft">Сохранить черновик</button><button class="btn" type="submit">Отправить учителю →</button></div></form><aside class="column-stack"><div class="panel"><h3>Памятка автора</h3><ul class="list-plain small muted"><li>Тезис — одна конкретная мысль.</li><li>Аргумент — проверяемый пример.</li><li>Логика — связь между примером и тезисом.</li><li>Вывод — не повтор дословно, а обобщение.</li></ul><a class="btn pale full" href="ai.html${m?'?material_id='+encodeURIComponent(m.id):''}">Получить наводящие вопросы ↗</a></div><div class="panel"><h3>Первая и улучшенная версии</h3><div class="small muted">После заполнения сравни:</div><div class="quote small" style="margin-top:10px">${e((draft.first||'Первую версию увидишь здесь.').slice(0,400))}</div><div class="quote small" style="margin-top:10px">${e((draft.revised||'Исправленную версию увидишь здесь.').slice(0,400))}</div></div></aside></div>`}`}
function renderDictionary(){const query=state.search.toLocaleLowerCase(),terms=CONTENT.dictionary.filter(x=>(x.ru+' '+x.kz+' '+x.meaning+' '+x.example).toLocaleLowerCase().includes(query));return `${intro('RU / KZ','Русский без паники','Сложные понятия простым русским с пояснением на казахском. Учебные карточки и самопроверка.')}${statusBanner()}<form id="dict-search" class="toolbar"><div class="field"><label for="dict-input">Найти слово</label><input id="dict-input" value="${e(state.search)}" placeholder="Тезис, аргумент, стиль…"></div><button class="btn" type="submit">Найти</button></form>${terms.length?`<div class="vocab">${terms.map(v=>`<article class="panel"><div class="word">${e(v.ru)}</div><div class="translation">${e(v.kz)}</div><p class="small" style="margin:13px 0">${e(v.meaning)}</p><div class="example">Пример: ${e(v.example)}</div></article>`).join('')}</div>`:empty('Слово не найдено','Попробуй другой термин.')}<div class="section-head"><h2>Мини-самопроверка</h2></div><div class="panel"><h3>Что такое аргумент?</h3><div class="choices"><label class="choice"><input type="radio" name="vocab" value="0">Красивое, но случайное слово</label><label class="choice"><input type="radio" name="vocab" value="1">Доказательство в поддержку тезиса</label><label class="choice"><input type="radio" name="vocab" value="2">Название произведения</label></div><div class="form-actions"><button id="dict-check" class="btn">Проверить себя</button></div></div>`}
function renderAI(){const selected=qs.get('material_id')||state.selectedMaterial||'';const materials=state.materials||[];return `${intro('LIVE · WORKERS AI','Не списывай, подумай!','Настоящий генеративный AI: не пишет сочинение за тебя, а помогает сформулировать тезис, найти доказательства и улучшить черновик.')}${statusBanner()}<div class="split"><div class="panel"><div class="profile-card"><div class="avatar">✦</div><div><b>AI-наставник</b><div class="micro muted">Cloudflare Workers AI · ответы формируются заново</div></div></div><div class="chat" id="chat" aria-live="polite">${state.chat.length?state.chat.map(x=>`<div class="bubble ${x.role==='user'?'user':'bot'}">${e(x.text)}</div>`).join(''):`<div class="bubble bot">Привет! Какую тему ты изучаешь? Расскажи, что уже понял(а), и вместе найдём следующий шаг.</div>`}</div><form id="ai-form"><div class="field"><label for="ai-material">Материал для контекста (необязательно)</label><select id="ai-material" name="material_id"><option value="">Поиск подходящего материала автоматически</option>${materials.map(m=>`<option value="${e(m.id)}" ${selected===m.id?'selected':''}>${e(m.title)}</option>`).join('')}${selected&&!materials.find(m=>m.id===selected)?`<option value="${e(selected)}" selected>Выбранный материал из библиотеки</option>`:''}</select></div><div class="field" style="margin-top:13px"><label for="ai-message">Твой вопрос</label><textarea id="ai-message" required minlength="4" maxlength="1250" placeholder="Помоги найти два аргумента. Я думаю, что…"></textarea></div><div class="form-actions"><button class="btn" type="submit" ${!isConfigured()?'disabled':''}>Спросить AI ↗</button><button class="btn soft" type="button" id="ai-clear">Очистить чат</button></div></form><p class="micro muted">Не отправляй AI ФИО, номера телефонов, фото или другую личную информацию. Сообщения чата не записываются в D1.</p></div><aside class="column-stack"><div class="panel subtle"><span class="badge">ПРАВИЛО ПОМОЩНИКА</span><h3 style="margin-top:12px">Мысль — твоя. Вопросы — наши.</h3><p class="muted small">AI задаёт наводящие вопросы и анализирует аргументацию. Он может ошибаться, поэтому проверяй факты и цитаты.</p></div><div class="panel"><h3>Примеры вопросов</h3>${['Как сформулировать точный тезис?','Помоги проверить аргументы моего черновика.','Объясни сложноподчинённое предложение простыми словами.'].map(s=>`<button type="button" class="btn soft full" style="justify-content:flex-start;margin-top:8px;white-space:normal;text-align:left" data-ai-example="${e(s)}">${e(s)}</button>`).join('')}</div></aside></div>`}
function renderProgress(){
 const x=state.progress;
 const header=intro('МОИ ДОСТИЖЕНИЯ','Мой прогресс','Только реальные результаты из D1. Никакой вымышленной статистики.');
 const locked=guard();if(locked)return header+statusBanner()+locked;
 if(state.loading)return header+statusBanner()+spinner();
 const attempts=x?.attempts||[],subs=x?.submissions||[];
 const latest=phase=>attempts.find(a=>a.kind==='diagnostic'&&a.phase===phase);
 const before=latest('pre'),after=latest('post');
 const avg=attempts.length?Math.round(attempts.reduce((v,a)=>v+a.score/a.total*100,0)/attempts.length):null;
 const diploma=!!(before&&after&&subs.some(s=>s.type==='essay'));
 const statsHtml=`<div class="stats">${stat('Пройдено тренировок',attempts.length)}${stat('Средний результат',avg===null?'—':avg+'%')}${stat('Работы на проверку',subs.length)}${stat('Диагностика до/после',before&&after?'✓':'—')}</div>`;
 let bars=empty('Пока нет результатов','Начни с входной диагностики.');
 if(before||after)bars=`<div class="progress-bars">${[['До',before],['После',after]].map(([label,r],i)=>`<div class="bar-row"><span>${label}</span><div class="bar-track"><div class="bar-fill ${i?'after':''}" style="width:${r?Math.round(r.score/r.total*100):0}%"></div></div><span>${r?Math.round(r.score/r.total*100)+'%':'—'}</span></div>`).join('')}</div>`;
 const achievements=`<div class="panel"><h3>Личные достижения</h3><p class="small muted">Достижения присуждаются по реально выполненным действиям.</p><div class="column-stack"><div class="callout">${attempts.length?'✓':'○'} Первый шаг · 1 тренировка</div><div class="callout">${before&&after?'✓':'○'} Увидеть прогресс · обе диагностики</div><div class="callout">${subs.some(s=>s.type==='essay')?'✓':'○'} Автор мысли · своё сочинение</div></div></div>`;
 const progressSection=`<div class="section-head"><h2>Рост навыков</h2></div><div class="split"><div class="panel"><h3>Сравнение «до / после»</h3>${bars}<div class="form-actions"><a class="btn" href="diagnostic.html">Пройти диагностику →</a></div></div>${achievements}</div>`;
 const historyRows=attempts.map(a=>`<tr><td>${e(a.created_at)}</td><td>${e(a.kind)} ${e(a.phase||a.category||'')}</td><td><b>${a.score}/${a.total}</b></td></tr>`).join('');
 const history=attempts.length?`<div class="panel"><div class="table-scroll"><table class="datatable"><thead><tr><th>Дата</th><th>Действие</th><th>Результат</th></tr></thead><tbody>${historyRows}</tbody></table></div></div>`:empty('История пуста','Сохрани первое задание, чтобы увидеть результат.');
 const submissionRows=subs.map(s=>`<div class="result-item"><b>${e(s.type)}</b> · ${e(s.created_at)} <span class="badge ${s.status==='reviewed'?'':'orange'}">${s.status==='reviewed'?'Проверено учителем':'Ожидает проверки'}</span>${s.teacher_note?`<div class="teacher-response">Комментарий учителя: ${e(s.teacher_note)}${Object.keys(s.rubric||{}).length?`<div class="micro">Рубрика: ${e(JSON.stringify(s.rubric))}</div>`:''}</div>`:''}</div>`).join('');
 const submissionSection=subs.length?`<div class="panel">${submissionRows}</div>`:empty('Пока нет письменных работ','Работы появляются после отправки, а не просто после заполнения формы.');
 const certificatePanel=`<div class="panel" style="margin-top:18px"><h3>Сертификат самостоятельного мышления</h3><p class="small muted">Учебный сертификат платформы, не официальный документ. Доступен после двух диагностик и отправки сочинения.</p><button class="btn" id="print-certificate" ${diploma?'':'disabled'}>Печать сертификата</button></div>`;
 const certificatePrint=diploma?`<div class="print-only cert-page"><h1>СЕРТИФИКАТ</h1><p>Учебный сертификат об освоении курса самостоятельного мышления</p><h2>${e(state.user.handle)}</h2><p>Диагностика и сочинение завершены · Антисписывание</p><p>Не является официальным документом</p></div>`:'';
 return header+statusBanner()+statsHtml+progressSection+`<div class="section-head"><h2>История результатов</h2></div>`+history+`<div class="section-head"><h2>Письменные работы</h2></div>`+submissionSection+certificatePanel+certificatePrint;
}
function renderTeacher(){
 const header=intro('ДЛЯ ПЕДАГОГА','Кабинет учителя','Результаты учащихся только под условными кодами; динамика диагностики, письменные работы и проверка по рубрике.');
 const locked=guard('teacher');if(locked)return header+statusBanner()+locked;
 if(state.loading)return header+statusBanner()+spinner();
 const x=state.teacher||{},rows=x.students||[],submissions=x.submissions||[];
 const overview=`<div class="stats">${stat('Ученики',rows.length)}${stat('Входная диагностика',rows.filter(r=>r.pre!==null).length)}${stat('Итоговая диагностика',rows.filter(r=>r.post!==null).length)}${stat('Письменные работы',submissions.length)}</div>`;
 const studentRows=rows.map(r=>`<tr><td><b>${e(r.handle)}</b></td><td>${r.attempts}</td><td>${r.pre??'—'}</td><td>${r.post??'—'}</td><td>${r.average===null?'—':r.average+'%'}</td></tr>`).join('');
 const studentTable=rows.length?`<div class="panel"><div class="table-scroll"><table class="datatable"><thead><tr><th>Код ученика</th><th>Тренировки</th><th>До / 20</th><th>После / 20</th><th>Средний результат</th></tr></thead><tbody>${studentRows}</tbody></table></div><p class="micro muted">Видны первые 250 условных кодов. Для масштабного журнала потребуется серверная пагинация.</p></div>`:empty('Пока нет зарегистрированных учеников','После появления учеников таблица заполнится автоматически.');
 const submissionCards=submissions.map(s=>{
  const options=field=>[0,1,2,3].map(n=>`<option value="${n}" ${s.rubric?.[field]===n?'selected':''}>${n}</option>`).join('');
  const fields=[['meaning','Смысл'],['evidence','Доказательства'],['logic','Логика'],['language','Речь']].map(([name,label])=>`<div class="field"><label for="${name}-${e(s.id)}">${label} (0–3)</label><select id="${name}-${e(s.id)}" name="${name}">${options(name)}</select></div>`).join('');
  return `<article class="panel"><div class="question-meta"><span><b>${e(s.handle)}</b> · ${e(s.type)}</span><span>${e(s.created_at)} · ${e(s.status)}</span></div><div class="quote small">${e(JSON.stringify(s.payload,null,2)).slice(0,7000)}</div><form class="review-form" data-id="${e(s.id)}" data-version="${s.version}"><div class="fields" style="margin-top:15px">${fields}<div class="field wide"><label for="note-${e(s.id)}">Комментарий учителя</label><textarea id="note-${e(s.id)}" name="note" maxlength="1800">${e(s.teacher_note||'')}</textarea></div></div><div class="form-actions"><button class="btn tiny">Сохранить проверку</button></div></form></article>`;
 }).join('');
 const workList=submissions.length?`<div class="column-stack">${submissionCards}</div>`:empty('Работ пока нет','Отправленные учениками сочинения и другие тексты появятся здесь.');
 return header+statusBanner()+overview+`<div class="section-head"><h2>Класс · сводная таблица</h2><button class="btn soft tiny" id="teacher-export">Экспорт CSV ↓</button></div>`+studentTable+`<div class="section-head"><h2>Письменные работы</h2></div>`+workList+`<div class="form-actions"><a class="btn soft" href="admin.html">Управлять материалами →</a></div>`;
}
function adminForm(){let m=state.editing||{},ex=m.extra||{};const id=m.id;return `<form id="material-form" class="panel"><div class="question-meta"><span><b>${id?'Редактировать материал':'Новый учебный материал'}</b></span><span>${id?'Версия '+m.version:'Версия 1 при создании'}</span></div><div class="fields"><div class="field"><label for="mat-title">Название *</label><input id="mat-title" name="title" required minlength="3" maxlength="140" value="${e(m.title||'')}"></div><div class="field"><label for="mat-category">Категория *</label><select id="mat-category" name="category">${Object.entries(colorCategories).map(([val,label])=>`<option value="${val}" ${m.category===val?'selected':''}>${e(label)}</option>`).join('')}</select></div><div class="field wide"><label for="mat-description">Краткое описание</label><textarea id="mat-description" name="description" maxlength="500" rows="2">${e(m.description||'')}</textarea></div><div class="field wide"><label for="mat-content">Основной текст *</label><textarea id="mat-content" name="content" maxlength="20000" rows="8">${e(m.content||'')}</textarea></div><div class="field"><label for="mat-author">Авторский кредит (если известен)</label><input id="mat-author" name="author_label" value="${e(m.author_label||'Авторский учебный материал')}"></div><div class="field"><label for="mat-level">Класс</label><input id="mat-level" name="level" maxlength="20" value="${e(m.level||'9')}"></div><div class="field wide"><label for="mat-question">Для категории «Задание»: вопрос</label><input id="mat-question" name="question" maxlength="500" value="${e(ex.question||'')}"></div><div class="field wide"><label for="mat-options">Варианты ответа (по одному на строку, 2–5)</label><textarea id="mat-options" name="options" maxlength="1100" rows="4">${e((ex.options||[]).join('\n'))}</textarea></div><div class="field"><label for="mat-correct">Номер верного ответа (1–5)</label><input type="number" id="mat-correct" name="answer" min="1" max="5" value="${Number.isInteger(ex.answer_index)?ex.answer_index+1:1}"></div><div class="field"><label for="mat-explain">Пояснение к ответу</label><input id="mat-explain" name="explanation" value="${e(ex.explanation||'')}"></div><div class="field"><label for="mat-video">Видео: только внешняя ссылка</label><input type="url" id="mat-video" name="video_url" value="${e(m.video_url||'')}" placeholder="https://..."></div><div class="field"><label for="mat-reference">Ссылка на источник (если есть)</label><input type="url" id="mat-reference" name="reference_url" value="${e(m.reference_url||'')}" placeholder="https://..."></div><div class="field"><label for="mat-coverfile">Изображение обложки (JPG/PNG/WebP, до 3 МБ)</label><input type="file" id="mat-coverfile" accept="image/jpeg,image/png,image/webp"></div><div class="field"><label for="mat-docfile">Документ (PDF, до 10 МБ)</label><input type="file" id="mat-docfile" accept="application/pdf"></div><div class="field wide"><input type="hidden" name="cover_key" id="mat-cover-key" value="${e(m.cover_key||'')}"><input type="hidden" name="attachment_key" id="mat-attachment-key" value="${e(m.attachment_key||'')}"><div class="micro muted" id="upload-status">${m.cover_key?'Обложка загружена. ':''}${m.attachment_key?'Документ загружен.':''} Файлы сохраняются только после успешной загрузки в R2.</div></div><div class="field"><label for="mat-status">Статус</label><select id="mat-status" name="status"><option value="draft" ${m.status==='draft'?'selected':''}>Черновик</option><option value="published" ${m.status==='published'?'selected':''}>Опубликовать</option><option value="archived" ${m.status==='archived'?'selected':''}>Архив</option></select></div></div><div class="form-actions"><button class="btn" type="submit">${id?'Сохранить изменения':'Создать материал'} →</button><button class="btn soft" type="button" id="admin-cancel">Новая запись</button></div><p class="micro muted">Одновременная правка с другого устройства вызовет конфликт версий 409 — изменения не перезапишутся молча.</p></form>`}
function renderAdmin(){
 const header=intro('CMS · ДЛЯ ПЕДАГОГА','Управление материалами','Создавай, редактируй, публикуй и архивируй без изменения кода. Данные хранятся в общей базе D1.');
 const locked=guard('teacher');if(locked)return header+statusBanner()+locked;
 if(state.loading)return header+statusBanner()+spinner();
 const materials=state.data?.items||[];
 const entries=materials.map(m=>{
  const publish=m.status==='published'?'':`<button class="btn tiny pale" data-status-id="${e(m.id)}" data-status-to="published">Опубликовать</button>`;
  const archive=m.status==='archived'?'':`<button class="btn tiny danger" data-status-id="${e(m.id)}" data-status-to="archived">В архив</button>`;
  return `<div class="result-item"><b>${e(m.title)}</b><div class="micro muted">${e(colorCategories[m.category])} · ${e(m.status)} · v${m.version}</div><div class="form-actions"><button class="btn tiny soft" data-edit-id="${e(m.id)}">Изменить</button>${publish}${archive}</div></div>`;
 }).join('');
 const materialList=materials.length?entries+pager():empty('Нет материалов','Создай первую запись слева.');
 const searchPanel=`<div class="panel"><h3>Материалы (${state.data?.total??0})</h3><div class="field"><label for="admin-q">Поиск по материалам</label><input id="admin-q" value="${e(state.search)}" placeholder="Название, текст…"></div><div class="form-actions"><button class="btn tiny soft" id="admin-find">Искать</button></div>${materialList}</div>`;
 const hints=`<div class="panel subtle"><h3>Публикация</h3><p class="small muted">Только опубликованные записи видны в библиотеке и контексте AI. Вопросы категории «Задание» доступны в тестовом тренажёре.</p></div>`;
 const staff=state.user.role==='admin'?`<form class="panel" id="add-teacher"><h3>Создать аккаунт учителя</h3><div class="field"><label for="new-username">Логин</label><input id="new-username" name="handle" minlength="3" maxlength="24" required pattern="[A-Za-z0-9_-]{3,24}"></div><div class="field" style="margin-top:10px"><label for="new-pass">Временный пароль (мин. 10 символов)</label><input id="new-pass" name="password" type="password" minlength="10" maxlength="128" required></div><div class="form-actions"><button class="btn tiny" type="submit">Создать учителя</button></div></form>`:'';
 return header+statusBanner()+`<div class="split"><section>${adminForm()}</section><aside class="column-stack">${searchPanel}${hints}${staff}</aside></div>`;
}
function renderContent(){switch(page){case'index':return renderHome();case'login':return renderLogin();case'library':return renderLibrary();case'material':return renderMaterial();case'diagnostic':return renderQuiz('diagnostic');case'tests':return renderQuiz(qs.get('material_id')?'task':'quiz');case'catch':return renderCatch();case'error404':return renderError404();case'battle':return renderBattle();case'detective':return renderDetective();case'gps':return renderGps();case'essay':return renderEssay();case'dictionary':return renderDictionary();case'ai':return renderAI();case'progress':return renderProgress();case'teacher':return renderTeacher();case'admin':return renderAdmin();default:return empty('Страница не найдена')}}
function render(){root.innerHTML=htmlShell(renderContent()+`<footer class="footer">АНТИСПИСЫВАНИЕ · 9 класс · Авторские учебные материалы · <span class="muted">© 2026. Не является официальной образовательной платформой.</span></footer>`);if(state.chat.length&&page==='ai'){$('#chat')?.scrollTo({top:$('#chat').scrollHeight})}}
async function load(){state.error=null;state.loading=true;render();try{
 if(page==='library'){state.data=await api(`/api/materials?page=${state.pg}&category=${encodeURIComponent(state.category)}&q=${encodeURIComponent(state.search)}`)}
 else if(page==='material'){state.currentMaterial=(await api('/api/materials/'+encodeURIComponent(qs.get('id')||''))).item}
 else if(page==='ai'){const x=await api('/api/materials?page=1');state.materials=x.items||[]}
 else if(page==='diagnostic'||page==='tests'){let kind=page==='diagnostic'?'diagnostic':qs.get('material_id')?'task':'quiz';const params=new URLSearchParams({kind,phase:state.phase,category:state.category});if(kind==='task')params.set('material_id',qs.get('material_id'));const x=await api('/api/exercises?'+params);state.exercises=x.items||[]}
 else if(['catch','error404','battle','detective'].includes(page)){const kind=({catch:'catch',error404:'error404',battle:'battle',detective:'detective'})[page];state.exercises=(await api('/api/exercises?kind='+kind)).items||[]}
 else if(page==='progress'&&state.user){state.progress=await api('/api/me/progress')}
 else if(page==='teacher'&&['teacher','admin'].includes(state.user?.role)){state.teacher=await api('/api/teacher/overview')}
 else if(page==='admin'&&['teacher','admin'].includes(state.user?.role)){state.data=await api(`/api/materials?scope=manage&page=${state.pg}&q=${encodeURIComponent(state.search)}`)}
 else if(page==='essay'){if(qs.get('material_id'))state.currentMaterial=(await api('/api/materials/'+encodeURIComponent(qs.get('material_id')))).item;if(state.user)await loadDraft('essay')}
 else if(page==='gps'&&state.user)await loadDraft('gps');
 }catch(err){state.error=err.message;state.data=page==='library'||page==='admin'?null:state.data}finally{state.loading=false;render()}}
async function loadDraft(type){const x=await api('/api/drafts?type='+type+(qs.get('material_id')?'&material_id='+encodeURIComponent(qs.get('material_id')):''));state.draft=x.draft;state.draftVersion=x.draft?.version||0;if(type==='gps'&&x.draft?.payload?.steps)state.answers=x.draft.payload.steps.reduce((a,v,i)=>(a[i]=v,a),{})}
async function init(){try{if(isConfigured()){const {user}=await api('/api/me');state.user=user; if(!user&&getToken())setToken('')}}catch(err){state.error=err.message}render();await load()}
function values(form){return Object.fromEntries(new FormData(form).entries())}
async function submitQuiz(){const qs0=state.exercises;const kind=page==='diagnostic'?'diagnostic':new URLSearchParams(location.search).get('material_id')?'task':'quiz';const current=qs0[state.index];if(!Object.prototype.hasOwnProperty.call(state.answers,current.id))return toast('Выбери вариант ответа.',true);if(state.index<qs0.length-1){state.index++;render();return}
 const responses=qs0.map(q=>({id:q.id,answer:Number(state.answers[q.id])}));if(responses.some(r=>Number.isNaN(r.answer)))return toast('Ответь на все вопросы.',true);
 const result=await api('/api/exercises/submit',{method:'POST',body:{kind,phase:state.phase,category:state.category,material_id:qs.get('material_id')||null,responses}});state.grade=result.result;render();toast('Результат сохранён в D1.');scrollTo({top:0,behavior:'smooth'});
}
async function submitGame(kind,payload){const x=await api('/api/exercises/submit',{method:'POST',body:{kind,...payload}});state.grade=x.result;render();toast('Результат сохранён на сервере.');scrollTo({top:0,behavior:'smooth'})}
function writeEssayPayload(form){let x=values(form);return {topic:String(x.topic||''),thesis:String(x.thesis||'').trim(),arg1:String(x.arg1||'').trim(),arg2:String(x.arg2||'').trim(),plan:String(x.plan||'').trim(),first:String(x.first||'').trim(),revised:String(x.revised||'').trim(),conclusion:String(x.conclusion||'').trim()}}
async function saveDraft(type,payload){const x=await api('/api/drafts',{method:'PUT',body:{type,material_id:qs.get('material_id')||null,payload,version:state.draftVersion}});state.draftVersion=x.draft.version;state.draft={payload,version:state.draftVersion};render();toast('Черновик действительно сохранён в D1.');}
function readGps(){const steps=CONTENT.gpsPrompts.map((_,i)=>i===state.index?($('#gps-response')?.value.trim()||''):(state.answers[i]||''));return steps}
async function exportCsv(){const students=state.teacher?.students||[];if(!students.length)return toast('Әзірге экспорттауға дерек жоқ.',true);
 const rows=[['Код ученика','Тренировки','До /20','После /20','Средний результат %'],...students.map(s=>[s.handle,s.attempts,s.pre??'',s.post??'',s.average??''])];const csv='\ufeff'+rows.map(r=>r.map(v=>{let txt=String(v);if(/^[=+@\-\t\r]/.test(txt))txt="'"+txt;return '"'+txt.replaceAll('"','""')+'"'}).join(';')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const href=URL.createObjectURL(blob);const a=document.createElement('a');a.href=href;a.download='antispisyvanie-class-report.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),3000)}
async function submitForm(form){const data=values(form);switch(form.id){
 case 'login-form':case 'register-form':{
  const action=form.id==='login-form'?'login':'register';const x=await api(`/api/auth/${action}`,{method:'POST',body:{handle:data.handle,password:data.password}});setToken(x.token);state.user=x.user;location.href=x.user.role==='student'?'progress.html':'teacher.html';break;
 }
 case 'search-library':state.search=data.search||'';state.category=data.category||'all';state.pg=1;await load();break;
 case 'dict-search':state.search=$('#dict-input')?.value||'';render();break;
 case 'catch-form':{const item=state.exercises[state.gameIdx%state.exercises.length];const marks=item.claims.map((_,i)=>!!form.querySelector(`input[name="claim"][value="${i}"]:checked`));const reason=$('#catch-reason').value.trim();if(!marks.some(Boolean))return toast('Отметь хотя бы одно подозрительное утверждение.',true);await submitGame('catch',{index:state.gameIdx%state.exercises.length,marks,reason});break}
 case 'error-form':{const q=state.exercises.find(v=>v.type===state.gameType&&v.level===state.gameLevel);await submitGame('error404',{index:Number(q.id.slice(6)),answer:Number(data.answer)});break}
 case 'battle-form':{const count=state.exercises[0].statements.length;const choices=Array.from({length:count},(_,i)=>!!form.querySelector(`input[name="claim"][value="${i}"]:checked`));await submitGame('battle',{choices,position:data['position']||$('#battle-position').value.trim()});break}
 case 'detective-form':{await submitGame('detective',{index:state.gameIdx%state.exercises.length,answer:Number(data.answer),detail:Number(data.detail),reason:$('#det-reason').value.trim()});break}
 case 'gps-form':{const txt=$('#gps-response')?.value.trim()||'';if(txt.length<12)return toast('Напиши хотя бы 12 символов.',true);state.answers[state.index]=txt;if(state.index<4){state.index++;render();break}const steps=CONTENT.gpsPrompts.map((_,i)=>state.answers[i]||'');const out=await api('/api/submissions',{method:'POST',body:{type:'gps',payload:{steps}}});state.gpsCompleted=steps;render();toast('Маршрут отправлен учителю. ID: '+out.submission.id.slice(0,8));break}
 case 'essay-form':{const payload=writeEssayPayload(form);const parts=['thesis','arg1','arg2','first','revised','conclusion'];if(parts.filter(k=>payload[k].length>=20).length<4)return toast('Заполни хотя бы 4 основные части по 20 символов.',true);const out=await api('/api/submissions',{method:'POST',body:{type:'essay',material_id:qs.get('material_id')||null,payload}});state.essaySent=out.submission.id;render();toast('Сочинение отправлено учителю.');break}
 case 'ai-form':{let msg=$('#ai-message').value.trim();if(!msg)return;let material_id=$('#ai-material').value;state.selectedMaterial=material_id;state.chat.push({role:'user',text:msg});render();const target=$('#chat');if(target)target.setAttribute('aria-busy','true'); try{const x=await api('/api/ai/chat',{method:'POST',timeout:31000,body:{message:msg,language:lang,material_id}});state.chat.push({role:'bot',text:x.answer+(x.source_materials?.length?'\n\nКонтекст: '+x.source_materials.map(v=>v.title).join(', '):'')});render()}catch(err){state.chat.pop();render();throw err}break}
 case 'material-form':{
 const payload={title:data.title,description:data.description,category:data.category,status:data.status,content:data.content,level:data.level,author_label:data.author_label,video_url:data.video_url,reference_url:data.reference_url,cover_key:data.cover_key,attachment_key:data.attachment_key,extra:{question:data.question,options:String(data.options||'').split('\n').map(x=>x.trim()).filter(Boolean),answer_index:Number(data.answer)-1,explanation:data.explanation}};
 const editing=state.editing;if(editing)await api('/api/materials/'+editing.id,{method:'PUT',body:{...payload,version:editing.version}});else await api('/api/materials',{method:'POST',body:payload});state.editing=null;state.pg=1;toast('Материал сақталды. Мәртебесі: '+data.status);await load();break;
 }
 case 'add-teacher':await api('/api/admin/users',{method:'POST',body:{handle:data.handle,password:data.password,role:'teacher'}});toast('Мұғалім аккаунты құрылды. Құпиясөзді қауіпсіз арнамен беріңіз.');form.reset();break;
 default:if(form.matches('.review-form')){
  const rubric={meaning:Number(data.meaning),evidence:Number(data.evidence),logic:Number(data.logic),language:Number(data.language)};await api('/api/teacher/review/'+form.dataset.id,{method:'PATCH',body:{version:Number(form.dataset.version),note:data.note,rubric}});toast('Бағалау серверде сақталды.');await load();}
 }}
async function handleClick(evt){const a=evt.target.closest('button');if(!a)return;
 if(a.id==='nav-toggle'){const side=$('#sidebar'),cover=$('#mobile-cover');const show=!side.classList.contains('show');side.classList.toggle('show',show);cover.classList.toggle('show',show);a.setAttribute('aria-expanded',String(show));return}
 if(a.dataset.lang){lang=a.dataset.lang;localStorage.setItem('as.lang',lang);render();return}
 if(a.id==='logout'){await api('/api/auth/logout',{method:'POST'});setToken('');state.user=null;location.href='index.html';return}
 if(a.dataset.pageIndex){state.pg=Number(a.dataset.pageIndex);await load();return}
 if(a.dataset.quizCategory){state.category=a.dataset.quizCategory;state.grade=null;state.answers={};state.index=0;await load();return}
 if(a.dataset.phase){state.phase=a.dataset.phase;state.grade=null;state.answers={};state.index=0;await load();return}
 if(a.dataset.quizAction==='prev'){state.index=Math.max(0,state.index-1);render();return}
 if(a.dataset.quizAction==='next'){const q=state.exercises[state.index];const checked=$('input[name="answer"]:checked');if(checked)state.answers[q.id]=checked.value;await submitQuiz();return}
 if(a.id==='restart-exercise'){state.grade=null;state.index=0;state.answers={};if(page==='error404')state.gameLevel=state.gameLevel%3+1;render();return}
 if(a.id==='next-game'){state.gameIdx=(state.gameIdx+1)%Math.max(1,state.exercises.length);state.grade=null;render();return}
 if(a.dataset.errorType){state.gameType=a.dataset.errorType;state.grade=null;render();return}
 if(a.dataset.errorLevel){state.gameLevel=Number(a.dataset.errorLevel);state.grade=null;render();return}
 if(a.id==='gps-prev'){const txt=$('#gps-response')?.value||'';state.answers[state.index]=txt;state.index=Math.max(0,state.index-1);render();return}
 if(a.id==='gps-draft'){const steps=readGps();await saveDraft('gps',{steps});state.answers=steps.reduce((out,v,i)=>(out[i]=v,out),{});return}
 if(a.id==='essay-draft'){const form=$('#essay-form');if(form)await saveDraft('essay',writeEssayPayload(form));return}
 if(a.id==='dict-check'){const ans=$('input[name="vocab"]:checked');if(!ans)return toast('Выбери ответ.',true);toast(ans.value==='1'?'Правильно! Аргумент — доказательство.':'Попробуй ещё раз: аргумент помогает доказать тезис.',ans.value!=='1');return}
 if(a.dataset.aiExample){const input=$('#ai-message');if(input){input.value=a.dataset.aiExample;input.focus()}return}
 if(a.id==='ai-clear'){state.chat=[];render();return}
 if(a.id==='print-certificate'){window.print();return}
 if(a.id==='teacher-export'){await exportCsv();return}
 if(a.id==='admin-cancel'){state.editing=null;render();return}
 if(a.id==='admin-find'){state.search=$('#admin-q')?.value||'';state.pg=1;await load();return}
 if(a.dataset.editId){const x=state.data?.items?.find(m=>m.id===a.dataset.editId);if(!x)return;state.editing=await api('/api/materials/'+x.id).then(v=>v.item);render();$('#material-form')?.scrollIntoView({behavior:'smooth'});return}
 if(a.dataset.statusId){const x=state.data?.items?.find(m=>m.id===a.dataset.statusId);if(!x)return;const full=(await api('/api/materials/'+x.id)).item;const {id,version,...partial}=full;const payload={...partial,status:a.dataset.statusTo,version};await api('/api/materials/'+x.id,{method:'PUT',body:payload});toast('Мәртебе өзгертілді: '+a.dataset.statusTo);await load();return}
}
async function handleUpload(evt){const el=evt.target;if(!['mat-coverfile','mat-docfile'].includes(el.id))return;const file=el.files?.[0];if(!file)return;const max=el.id==='mat-coverfile'?3*1024*1024:10*1024*1024;if(file.size>max)return toast('Файл көлемі рұқсат етілген мөлшерден үлкен.',true);const status=$('#upload-status');status.textContent='Файл жүктеліп жатыр…';try{const result=await api('/api/media',{method:'POST',headers:{'Content-Type':file.type},body:file,timeout:35000});const target=$(el.id==='mat-coverfile'?'#mat-cover-key':'#mat-attachment-key');target.value=result.key;status.textContent='Файл R2 қоймасына жүктелді: '+file.name;toast('Файл серверде сақталды. Материалды бөлек сақтаңыз.')}catch(err){status.textContent='Жүктеу қатесі: '+err.message;toast(err.message,true)}}
function renderGpsCompleted(){const a=state.gpsCompleted;if(!a)return null;return `${intro('МАРШРУТ АЯҚТАЛДЫ','Сен өз ойыңды қорғадың!','Барлық бес жауап D1 дерекқорына жазбаша жұмыс ретінде жіберілді.') }<div class="panel">${CONTENT.gpsPrompts.map((step,i)=>`<div class="result-item"><b>${i+1}. ${e(step.name)}</b><p class="text-reading small">${e(a[i])}</p>${a[i].length<35?'<span class="badge orange">Келесіде нақтырақ дәлел келтіруге тырыс</span>':''}</div>`).join('')}<div class="form-actions"><a class="btn" href="progress.html">Мой прогресс →</a></div></div>`}
const baseRenderGps=renderGps;
renderGps=function(){return state.gpsCompleted?renderGpsCompleted():baseRenderGps()};
const baseRenderEssay=renderEssay;
renderEssay=function(){return state.essaySent?`${intro('РАБОТА ОТПРАВЛЕНА','Твоя работа сохранена','Сочинение отправлено в D1 и доступно учителю для проверки.')}<div class="panel"><p>Статус: ожидает проверки. Комментарий появится в личном кабинете после сохранения учителем.</p><a class="btn" href="progress.html">Мой прогресс →</a></div>`:baseRenderEssay()};
document.addEventListener('click',event=>{if(event.target.id==='mobile-cover'){$('#sidebar')?.classList.remove('show');event.target.classList.remove('show');$('#nav-toggle')?.setAttribute('aria-expanded','false');return}handleClick(event).catch(err=>toast(err.message,true))});
document.addEventListener('submit',event=>{event.preventDefault();const form=event.target;const btn=form.querySelector('button[type="submit"]');if(btn?.disabled)return;if(btn)btn.disabled=true;submitForm(form).catch(err=>toast(err.message,true)).finally(()=>{if(btn?.isConnected)btn.disabled=false})});
document.addEventListener('change',event=>{handleUpload(event)});
init();
